import React, { useState, useEffect } from 'react';
import { Navigate } from 'react-router-dom';
import { useApp } from '../context/AppContext';
import {
  BarChart3,
  TrendingUp,
  Calendar,
  Clock,
  Target,
  Award,
  BookOpen,
  CheckSquare,
  Brain,
  Download,
  Filter
} from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
} from 'chart.js';
import { Line, Bar, Doughnut } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement
);

const Analytics: React.FC = () => {
  const { user, tasks, assignments, studySessions, darkMode } = useApp();
  const [timeRange, setTimeRange] = useState<'week' | 'month' | 'year'>('week');
  const [selectedMetric, setSelectedMetric] = useState<'all' | 'tasks' | 'assignments' | 'study'>('all');

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  // Calculate analytics data
  const calculateAnalytics = () => {
    const today = new Date();
    const weekStart = new Date(today);
    weekStart.setDate(today.getDate() - today.getDay());
    const monthStart = new Date(today.getFullYear(), today.getMonth(), 1);
    const yearStart = new Date(today.getFullYear(), 0, 1);

    const getDateRange = () => {
      switch (timeRange) {
        case 'week': return { start: weekStart, end: today };
        case 'month': return { start: monthStart, end: today };
        case 'year': return { start: yearStart, end: today };
        default: return { start: weekStart, end: today };
      }
    };

    const { start, end } = getDateRange();

    // Tasks analytics
    const tasksInRange = tasks.filter(task =>
      new Date(task.createdAt) >= start && new Date(task.createdAt) <= end
    );
    const completedTasksInRange = tasksInRange.filter(task => task.status === 'completed');
    const tasksCompletionRate = tasksInRange.length > 0
      ? (completedTasksInRange.length / tasksInRange.length) * 100
      : 0;

    // Assignments analytics
    const assignmentsInRange = assignments.filter(assignment =>
      new Date(assignment.dueDate) >= start && new Date(assignment.dueDate) <= end
    );
    const completedAssignmentsInRange = assignmentsInRange.filter(a => a.status === 'completed');
    const assignmentsCompletionRate = assignmentsInRange.length > 0
      ? (completedAssignmentsInRange.length / assignmentsInRange.length) * 100
      : 0;
    const averageGrade = assignments.filter(a => a.grade !== undefined).length > 0
      ? assignments.filter(a => a.grade !== undefined).reduce((sum, a) => sum + (a.grade || 0), 0) / assignments.filter(a => a.grade !== undefined).length
      : 0;

    // Study sessions analytics
    const studySessionsInRange = studySessions.filter(session =>
      new Date(session.completedAt) >= start && new Date(session.completedAt) <= end
    );
    const totalStudyTime = studySessionsInRange.reduce((total, session) => total + session.duration, 0);
    const averageSessionLength = studySessionsInRange.length > 0
      ? totalStudyTime / studySessionsInRange.length
      : 0;

    // Daily data for charts
    const generateDailyData = () => {
      const days = timeRange === 'week' ? 7 : timeRange === 'month' ? 30 : 365;
      const data = [];

      for (let i = days - 1; i >= 0; i--) {
        const date = new Date(today);
        date.setDate(date.getDate() - i);
        const dateStr = date.toISOString().split('T')[0];

        const dayTasks = tasks.filter(task =>
          task.createdAt.split('T')[0] === dateStr
        );
        const dayCompletedTasks = dayTasks.filter(task => task.status === 'completed');
        const dayStudyTime = studySessions
          .filter(session => session.completedAt.split('T')[0] === dateStr)
          .reduce((total, session) => total + session.duration, 0);

        data.push({
          date: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          tasks: dayTasks.length,
          completedTasks: dayCompletedTasks.length,
          studyTime: dayStudyTime
        });
      }

      return data;
    };

    return {
      tasks: {
        total: tasksInRange.length,
        completed: completedTasksInRange.length,
        completionRate: tasksCompletionRate,
        pending: tasksInRange.filter(t => t.status === 'pending').length
      },
      assignments: {
        total: assignmentsInRange.length,
        completed: completedAssignmentsInRange.length,
        completionRate: assignmentsCompletionRate,
        averageGrade: averageGrade,
        pending: assignmentsInRange.filter(a => a.status === 'pending').length
      },
      study: {
        totalSessions: studySessionsInRange.length,
        totalTime: totalStudyTime,
        averageSessionLength: averageSessionLength,
        dailyAverage: totalStudyTime / (timeRange === 'week' ? 7 : timeRange === 'month' ? 30 : 365)
      },
      dailyData: generateDailyData()
    };
  };

  const analytics = calculateAnalytics();

  // Chart configurations
  const chartColors = {
    primary: darkMode ? '#60a5fa' : '#3b82f6',
    secondary: darkMode ? '#34d399' : '#10b981',
    tertiary: darkMode ? '#fbbf24' : '#f59e0b',
    quaternary: darkMode ? '#f87171' : '#ef4444',
    background: darkMode ? '#1f2937' : '#ffffff',
    text: darkMode ? '#f3f4f6' : '#374151',
    grid: darkMode ? '#374151' : '#e5e7eb'
  };

  // Tasks completion chart
  const tasksCompletionData = {
    labels: analytics.dailyData.map(d => d.date),
    datasets: [
      {
        label: 'Tasks Created',
        data: analytics.dailyData.map(d => d.tasks),
        borderColor: chartColors.primary,
        backgroundColor: chartColors.primary + '20',
        tension: 0.4,
      },
      {
        label: 'Tasks Completed',
        data: analytics.dailyData.map(d => d.completedTasks),
        borderColor: chartColors.secondary,
        backgroundColor: chartColors.secondary + '20',
        tension: 0.4,
      }
    ]
  };

  // Study time chart
  const studyTimeData = {
    labels: analytics.dailyData.map(d => d.date),
    datasets: [
      {
        label: 'Study Time (minutes)',
        data: analytics.dailyData.map(d => d.studyTime),
        borderColor: chartColors.tertiary,
        backgroundColor: chartColors.tertiary + '20',
        tension: 0.4,
      }
    ]
  };

  // Status distribution chart
  const statusDistributionData = {
    labels: ['Completed', 'In Progress', 'Pending'],
    datasets: [
      {
        data: [
          analytics.tasks.completed,
          tasks.filter((t: any) => t.status === 'in-progress').length,
          analytics.tasks.pending
        ],
        backgroundColor: [
          chartColors.secondary,
          chartColors.primary,
          chartColors.tertiary
        ],
        borderWidth: 0
      }
    ]
  };

  // Subject distribution chart
  const subjectData = assignments.reduce((acc, assignment) => {
    acc[assignment.subject] = (acc[assignment.subject] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const subjectDistributionData = {
    labels: Object.keys(subjectData),
    datasets: [
      {
        data: Object.values(subjectData),
        backgroundColor: [
          chartColors.primary,
          chartColors.secondary,
          chartColors.tertiary,
          chartColors.quaternary,
          '#8b5cf6',
          '#ec4899'
        ],
        borderWidth: 0
      }
    ]
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: chartColors.text
        }
      },
      tooltip: {
        backgroundColor: chartColors.background,
        titleColor: chartColors.text,
        bodyColor: chartColors.text,
        borderColor: chartColors.grid,
        borderWidth: 1
      }
    },
    scales: {
      x: {
        grid: {
          color: chartColors.grid
        },
        ticks: {
          color: chartColors.text
        }
      },
      y: {
        grid: {
          color: chartColors.grid
        },
        ticks: {
          color: chartColors.text
        }
      }
    }
  };

  const doughnutOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom' as const,
        labels: {
          color: chartColors.text,
          padding: 20
        }
      },
      tooltip: {
        backgroundColor: chartColors.background,
        titleColor: chartColors.text,
        bodyColor: chartColors.text,
        borderColor: chartColors.grid,
        borderWidth: 1
      }
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Analytics & Insights
          </h1>
          <p className="text-gray-600 dark:text-gray-300 mt-2">
            Track your productivity and study patterns
          </p>
        </div>
        <div className="flex gap-2">
          <select
            value={timeRange}
            onChange={(e) => setTimeRange(e.target.value as any)}
            className="input"
          >
            <option value="week">Last Week</option>
            <option value="month">Last Month</option>
            <option value="year">Last Year</option>
          </select>
          <button className="btn-secondary">
            <Download className="w-4 h-4 mr-2" />
            Export
          </button>
        </div>
      </div>

      {/* Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Tasks Completed</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {analytics.tasks.completed}
              </p>
              <p className="text-xs text-gray-500 dark:text-gray-400">
                {analytics.tasks.completionRate.toFixed(1)}% completion rate
              </p>
            </div>
            <CheckSquare className="w-8 h-8 text-blue-500" />
          </div>
        </div>

        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Assignments</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {analytics.assignments.completed}
              </p>
              <p className="text-xs text-gray-500 dark:text-gray-400">
                {analytics.assignments.averageGrade > 0
                  ? `Avg: ${analytics.assignments.averageGrade.toFixed(1)}%`
                  : 'No grades yet'}
              </p>
            </div>
            <BookOpen className="w-8 h-8 text-green-500" />
          </div>
        </div>

        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Study Time</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {Math.floor(analytics.study.totalTime / 60)}h {analytics.study.totalTime % 60}m
              </p>
              <p className="text-xs text-gray-500 dark:text-gray-400">
                {Math.floor(analytics.study.dailyAverage)}m daily average
              </p>
            </div>
            <Brain className="w-8 h-8 text-purple-500" />
          </div>
        </div>

        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Sessions</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {analytics.study.totalSessions}
              </p>
              <p className="text-xs text-gray-500 dark:text-gray-400">
                {Math.floor(analytics.study.averageSessionLength)}m avg session
              </p>
            </div>
            <Target className="w-8 h-8 text-orange-500" />
          </div>
        </div>
      </div>

      {/* Charts Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Tasks Completion Trend */}
        <div className="card p-6">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            Tasks Completion Trend
          </h3>
          <div className="h-64">
            <Line data={tasksCompletionData} options={chartOptions} />
          </div>
        </div>

        {/* Study Time Trend */}
        <div className="card p-6">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            Study Time Trend
          </h3>
          <div className="h-64">
            <Line data={studyTimeData} options={chartOptions} />
          </div>
        </div>

        {/* Task Status Distribution */}
        <div className="card p-6">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            Task Status Distribution
          </h3>
          <div className="h-64">
            <Doughnut data={statusDistributionData} options={doughnutOptions} />
          </div>
        </div>

        {/* Subject Distribution */}
        <div className="card p-6">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
            Assignment Subjects
          </h3>
          <div className="h-64">
            <Doughnut data={subjectDistributionData} options={doughnutOptions} />
          </div>
        </div>
      </div>

      {/* Detailed Insights */}
      <div className="card p-6">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          Productivity Insights
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp className="w-5 h-5 text-blue-600" />
              <h4 className="font-medium text-blue-900 dark:text-blue-300">Task Performance</h4>
            </div>
            <p className="text-sm text-blue-800 dark:text-blue-300">
              {analytics.tasks.completionRate >= 80
                ? 'Excellent task completion rate! Keep up the great work.'
                : analytics.tasks.completionRate >= 60
                  ? 'Good progress. Try to complete more tasks to improve your productivity.'
                  : 'Room for improvement. Focus on completing tasks to boost your productivity.'}
            </p>
          </div>

          <div className="p-4 bg-green-50 dark:bg-green-900/20 rounded-lg">
            <div className="flex items-center gap-2 mb-2">
              <Award className="w-5 h-5 text-green-600" />
              <h4 className="font-medium text-green-900 dark:text-green-300">Assignment Success</h4>
            </div>
            <p className="text-sm text-green-800 dark:text-green-300">
              {analytics.assignments.completionRate >= 80
                ? 'Outstanding assignment completion! Your academic performance is strong.'
                : analytics.assignments.completionRate >= 60
                  ? 'Decent assignment completion. Stay consistent with your deadlines.'
                  : 'Focus on meeting assignment deadlines to improve your academic performance.'}
            </p>
          </div>

          <div className="p-4 bg-purple-50 dark:bg-purple-900/20 rounded-lg">
            <div className="flex items-center gap-2 mb-2">
              <Clock className="w-5 h-5 text-purple-600" />
              <h4 className="font-medium text-purple-900 dark:text-purple-300">Study Consistency</h4>
            </div>
            <p className="text-sm text-purple-800 dark:text-purple-300">
              {analytics.study.dailyAverage >= 60
                ? 'Excellent study consistency! You\'re building great habits.'
                : analytics.study.dailyAverage >= 30
                  ? 'Good study routine. Consider increasing daily study time for better results.'
                  : 'Try to establish a more consistent study routine to improve your learning.'}
            </p>
          </div>
        </div>
      </div>

      {/* Recent Activity */}
      <div className="card p-6">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          Recent Activity
        </h3>
        <div className="space-y-3">
          {studySessions.slice(-5).reverse().map((session, index) => (
            <div key={index} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-800 rounded-lg">
              <div className="flex items-center gap-3">
                <Brain className="w-5 h-5 text-purple-500" />
                <div>
                  <p className="font-medium text-gray-900 dark:text-white">
                    {session.subject || 'Study Session'}
                  </p>
                  <p className="text-sm text-gray-600 dark:text-gray-300">
                    {session.duration} minutes • {new Date(session.completedAt).toLocaleDateString()}
                  </p>
                </div>
              </div>
              <div className="text-right">
                <p className="text-sm font-medium text-gray-900 dark:text-white">
                  {new Date(session.completedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </p>
                {session.notes && (
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                    {session.notes.substring(0, 50)}...
                  </p>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Analytics;
